const SG_ECOSYSTEMS=[{key:"evergreen",name:"Tropical Evergreen",icon:"🌳"},{key:"deciduous",name:"Moist Deciduous",icon:"🍂"},{key:"dry",name:"Dry Deciduous & Thorn",icon:"🌵"},{key:"montane",name:"Subtropical Montane",icon:"⛰️"},{key:"water",name:"Sacred Water Body",icon:"💧"}],SG_REGIONS=[{key:"south",name:"South India",icon:"🌴"},{key:"west",name:"West India",icon:"🏜️"},{key:"east",name:"East India",icon:"🌾"},{key:"north",name:"North India",icon:"🏔️"},{key:"northeast",name:"Northeast India",icon:"🍃"}],SG_LOCAL_NAMES=[{state:"Kerala",names:"Kavu, Sarpa Kavu",note:"Sarpa Kavu are specifically serpent groves, often attached to a family compound."},{state:"Karnataka",names:"Devarakadu, Nagabana",note:"Kodagu district alone holds well over a thousand devarakadus."},{state:"Maharashtra",names:"Devrai, Deorai",note:"Concentrated along the Sahyadri crest in Pune, Satara and Raigad."},{state:"Goa",names:"Devrai, Pann",note:"Often associated with village deities and freshwater springs."},{state:"Tamil Nadu",names:"Kovil Kadu, Swami Shola",note:"Swami Sholas are the montane sacred patches of the Nilgiris."},{state:"Andhra Pradesh & Telangana",names:"Pavitravana",note:"Frequently attached to village temples and tank bunds."},{state:"Odisha",names:"Jahera, Thakuramma",note:"Jahera are the Santal sacred groves of western Odisha."},{state:"Jharkhand",names:"Sarna, Jaher",note:"Sal-dominated groves central to Sarna religious practice."},{state:"West Bengal",names:"Garamthan, Harithan, Sabitrithan",note:"Named for the deity each grove is dedicated to."},{state:"Meghalaya",names:"Law Kyntang, Law Lyngdoh",note:"Khasi groves managed by the Lyngdoh priestly clan."},{state:"Manipur",names:"Umang Lai, Gamkhap",note:"Umang Lai are Meitei forest-deity groves tied to the Lai Haraoba festival."},{state:"Rajasthan",names:"Oran, Kenkri, Vani",note:"Arid grazing-and-worship commons, often centred on a khejri tree."},{state:"Himachal Pradesh & Uttarakhand",names:"Devban, Deo Bhumi",note:"Temple forests attached to hill deities, often on ridge tops."},{state:"Chhattisgarh & Madhya Pradesh",names:"Sarna, Devgudi, Matigudi",note:"Devgudi are the shrine-groves of central Indian tribal communities."},{state:"Sikkim & Arunachal Pradesh",names:"Gumpa forests",note:"Forest patches attached to Buddhist monasteries and protected by them."},{state:"Gujarat",names:"Deo, Vandevi than",note:"Found in the Dangs and along the Sabarkantha belt."}],SACRED_GROVES=[{name:"Mawphlang Sacred Forest",icon:"🌲",localName:"Law Kyntang / Law Lyngdoh",state:"Meghalaya",region:"northeast",ecosystem:"montane",deity:"Labasa, the guardian deity of the Khasi clan",areaHa:78,community:"Khasi (Lyngdoh clan)",tagline:"Nothing may leave the forest — not even a fallen leaf",desc:"Perhaps the best known sacred grove in India, Mawphlang sits on the East Khasi Hills plateau amid otherwise open grassland. The contrast is the point: the grove shows what the surrounding landscape looked like before it was cleared. Its floor is deep in humus, and the trunks are thick with moss, orchids and epiphytes.",species:["Rudraksha (Elaeocarpus)","Castanopsis","Quercus oak species","Rare terrestrial orchids","Dense epiphyte and moss communities"],taboo:"Nothing may be removed from the grove — no timber, no leaf litter, not even a stone. The prohibition is absolute and is enforced by clan authority rather than by forest law."},{name:"Kodagu Devarakadu",icon:"☕",localName:"Devarakadu / Devara Kadu",state:"Karnataka",region:"south",ecosystem:"evergreen",deity:"Ayyappa, Bhagavathi and other village deities",areaHa:2550,community:"Kodava and other Kodagu communities",tagline:"Over a thousand groves in a single district",desc:"Kodagu (Coorg) has one of the densest concentrations of sacred groves anywhere in India — more than a thousand devarakadus scattered through a landscape otherwise dominated by coffee. Together they form a network of evergreen fragments in the Western Ghats, many of them the last intact patches in their valley.",species:["Dipterocarpus indicus","Wild nutmeg (Myristica)","Ficus species","Lion-tailed macaque habitat in larger groves","Endemic Western Ghats amphibians"],taboo:"Traditionally no felling, hunting or cultivation. Rules have loosened where groves passed from village committees to temple trusts, and encroachment by coffee is a recurring problem."},{name:"Iringole Kavu",icon:"🌿",localName:"Kavu",state:"Kerala",region:"south",ecosystem:"evergreen",deity:"Bhagavathy (Durga)",areaHa:20,community:"Local temple community, Perumbavoor",tagline:"A surviving lowland evergreen patch near Kochi",desc:"Iringole Kavu near Perumbavoor is among the largest surviving kavus in Kerala, a dense evergreen island in an area otherwise converted to rubber, settlement and roads. The temple sits inside the forest rather than the forest around the temple, which is the older pattern.",species:["Strychnos nux-vomica","Holigarna","Wild jack (Artocarpus hirsutus)","Climbing lianas","Resident and migratory bird species"],taboo:"Felling and even the collection of deadwood are prohibited. The grove is entered mainly for worship, and much of the interior is left undisturbed."},{name:"Mannarasala Grove",icon:"🐍",localName:"Sarpa Kavu",state:"Kerala",region:"south",ecosystem:"evergreen",deity:"Nagaraja, the serpent king",areaHa:6,community:"Mannarasala Illam, Alappuzha",tagline:"India's best known serpent grove",desc:"Sarpa kavus are small groves dedicated to serpent deities, historically maintained beside individual households across Kerala. Mannarasala is the largest and most famous, its shaded paths lined with thousands of serpent images among old trees.",species:["Dense shade-tolerant understorey","Ficus species","Medicinal climbers","Reptile and amphibian refuge"],taboo:"Serpent groves are entered with ritual restrictions; disturbing the grove is believed to bring illness or misfortune on the family that owns it."},{name:"Bhimashankar Devrai",icon:"🐿️",localName:"Devrai",state:"Maharashtra",region:"west",ecosystem:"evergreen",deity:"Bhimashankar (Shiva) and local village deities",areaHa:130,community:"Mahadev Koli and other Sahyadri communities",tagline:"Refuge of the Indian giant squirrel",desc:"The devrais around Bhimashankar on the Sahyadri crest protect the tall, closed-canopy forest that the Indian giant squirrel — the shekru, Maharashtra's state animal — needs to move without descending to the ground. The sacred patches and the wildlife sanctuary boundary reinforce each other.",species:["Indian giant squirrel (shekru)","Memecylon umbellatum","Mangifera indica","Endemic Sahyadri frogs","Hornbill species"],taboo:"Cutting is prohibited; only fallen wood may be taken in some villages, and even that is decided collectively."},{name:"Bhadariya Oran",icon:"🐐",localName:"Oran",state:"Rajasthan",region:"west",ecosystem:"dry",deity:"Bhadariya Mata",areaHa:4500,community:"Pastoral communities of Jaisalmer",tagline:"Desert commons held as sacred grazing land",desc:"Orans are arid commons dedicated to a deity, used for grazing but not for cultivation or felling. In a landscape with almost no other tree cover, they hold the khejri and rohida that sustain livestock, and they are among the last habitats for the Great Indian Bustard.",species:["Khejri (Prosopis cineraria)","Rohida (Tecomella undulata)","Ker and sangri shrubs","Blackbuck and chinkara","Great Indian Bustard habitat"],taboo:"Green wood may never be cut. Grazing is permitted, cultivation is not — the distinction is what has kept orans as open woodland rather than farmland."},{name:"Sarna Groves of Chotanagpur",icon:"🌳",localName:"Sarna / Jaher",state:"Jharkhand",region:"east",ecosystem:"deciduous",deity:"Sarna Mata (Jaher Era among the Santal)",areaHa:1200,community:"Oraon, Munda, Ho and Santal communities",tagline:"The sal groves at the centre of Sarna religion",desc:"Almost every traditional village across the Chotanagpur plateau has a sarna — a patch of sal forest that is the village's ritual centre rather than an ornament to it. The Sarhul spring festival, marking the flowering of the sal, is held there.",species:["Sal (Shorea robusta)","Mahua (Madhuca longifolia)","Palash (Butea monosperma)","Wild tuber and medicinal plant diversity"],taboo:"The grove is entered by the village priest (pahan) for ritual; felling is forbidden, and disputes over grove boundaries are treated as religious matters."},{name:"Chilkigarh Kanak Durga Grove",icon:"🌺",localName:"Garamthan",state:"West Bengal",region:"east",ecosystem:"deciduous",deity:"Kanak Durga",areaHa:24,community:"Jhargram district villages",tagline:"A medicinal-plant reservoir on the Dulung",desc:"Set on the bank of the Dulung river in Jhargram, this grove around the Kanak Durga temple has been surveyed as one of the richer concentrations of medicinal plant species in the region — a working pharmacopoeia that survives because the land was never cleared.",species:["Several hundred recorded plant species","Rauvolfia serpentina","Asparagus racemosus","Terminalia species","Resident bird and reptile populations"],taboo:"Collection of plants for medicine is permitted under customary rules; felling and clearing are not."},{name:"Umang Lai Groves",icon:"🎭",localName:"Umang Lai",state:"Manipur",region:"northeast",ecosystem:"deciduous",deity:"Umang Lai — the forest deities of Meitei tradition",areaHa:90,community:"Meitei communities of the Imphal valley",tagline:"Forest deities honoured through Lai Haraoba",desc:"Umang Lai are grove-shrines of the Meitei forest deities, spread across the Imphal valley. Each is tied to the Lai Haraoba festival, in which the deity's story is performed through dance and ritual over several days — the grove is the stage as much as the sanctuary.",species:["Valley deciduous species","Bamboo groves","Medicinal herbs used in Meitei practice","Urban-edge bird refuge"],taboo:"Maintained by a hereditary priesthood (maiba and maibi). Many groves have shrunk sharply as Imphal has expanded around them."},{name:"Hariyali Devi Grove",icon:"⛰️",localName:"Devban",state:"Uttarakhand",region:"north",ecosystem:"montane",deity:"Hariyali Devi",areaHa:550,community:"Villages of Rudraprayag district",tagline:"A Garhwal ridge forest under deity protection",desc:"The forest around the Hariyali Devi temple in Rudraprayag is protected by an unusually strict local code, and as a result carries oak and rhododendron cover of a quality now rare on comparable Garhwal ridges.",species:["Banj oak (Quercus leucotrichophora)","Rhododendron arboreum","Deodar at higher elevations","Himalayan monal","Musk deer records from adjoining slopes"],taboo:"Leather goods are traditionally not carried into the grove, and lopping of green branches is prohibited even during fodder shortage."},{name:"Khecheopalri Sacred Landscape",icon:"💧",localName:"Gumpa forest & sacred lake",state:"Sikkim",region:"northeast",ecosystem:"water",deity:"Revered in both Lepcha and Buddhist tradition",areaHa:90,community:"Lepcha and Bhutia communities of West Sikkim",tagline:"A wish-fulfilling lake inside a protected forest",desc:"Khecheopalri is a lake held sacred by both Lepcha and Buddhist communities, wrapped in a forest that is protected as part of the same sacred complex. Local tradition holds that leaves are not permitted to rest on the water — and birds are said to lift them off.",species:["Subtropical broadleaf forest","Orchid diversity","Wetland bird species","Freshwater fish protected from fishing"],taboo:"Fishing and swimming are prohibited. The catchment forest is treated as part of the sacred site rather than as separate land."},{name:"Nagabana of Dakshina Kannada",icon:"🐍",localName:"Nagabana",state:"Karnataka",region:"south",ecosystem:"evergreen",deity:"Naga (serpent) deities",areaHa:8,community:"Tulu-speaking coastal communities",tagline:"Serpent groves of the Tulu coast",desc:"Nagabanas are small serpent groves found across coastal Karnataka, often no larger than a household plot but numbering in the thousands. Individually tiny, collectively they preserve a meaningful amount of coastal evergreen vegetation in a heavily converted landscape.",species:["Coastal evergreen understorey","Ficus species","Pandanus","Reptile and amphibian refuge"],taboo:"Entry is restricted and ritually regulated. Conversion of a nagabana is considered a serious transgression against the household that holds it."}],SG_VALUES=[{title:"Relict vegetation",icon:"🌳",desc:"Many groves hold the last patch of climax forest in their landscape — the reference point for what the area looked like before conversion. Some are the only place a given species still grows locally."},{title:"Rare and endemic species",icon:"🦋",desc:"Because they were never logged or replanted, groves shelter species that vanished from surrounding land, including plants known only from a handful of sites."},{title:"Medicinal plant reservoirs",icon:"🌿",desc:"Groves function as living pharmacies for traditional medicine, and several have been surveyed as unusually rich in medicinal species per hectare."},{title:"Water recharge and springs",icon:"💧",desc:"Undisturbed soil and canopy in a grove absorb rainfall rather than shedding it, and many village springs emerge at the base of one — a direct, visible link between the taboo and the water supply."},{title:"Seed banks and gene pools",icon:"🌱",desc:"Groves supply seed and genetic diversity for restoring degraded land nearby, which plantation forestry cannot substitute for."},{title:"Pollinator and bird refuge",icon:"🐝",desc:"Flowering and fruiting trees in a grove sustain pollinators and frugivores that in turn service the surrounding farmland."},{title:"Carbon and soil",icon:"🍄",desc:"Undisturbed litter layers and root systems store carbon and hold soil that would otherwise be lost on steep or arid ground."},{title:"Wildlife corridors",icon:"🐅",desc:"Where groves cluster, as in Kodagu, they form stepping stones that let species move across a landscape of farms and settlement."}],SG_PRACTICES=[{title:"The absolute prohibition",icon:"🚫",desc:"The strongest groves operate on a total ban — nothing at all may be removed. Mawphlang is the classic example, where even a fallen leaf must stay inside."},{title:"Deadwood-only rules",icon:"🪵",desc:"Many groves allow collection of fallen wood but never cutting. The distinction is enforced socially, and villages argue over its edges."},{title:"Hereditary priesthood",icon:"🙏",desc:"A named office — the Lyngdoh among the Khasi, the pahan in Chotanagpur, the maiba in Manipur — holds authority over the grove and its calendar."},{title:"Entry restriction",icon:"🚪",desc:"Access may be limited by day, by gender, by caste or clan, or to ritual occasions only. Restriction is what keeps use levels low."},{title:"Annual festivals",icon:"🎊",desc:"Sarhul in Chotanagpur, Lai Haraoba in Manipur, and local temple festivals across the peninsula renew the community's relationship with the grove each year."},{title:"Oaths and dispute settlement",icon:"⚖️",desc:"Groves have served as places to swear oaths and settle village disputes, giving them a civic function alongside the religious one."},{title:"Belief as enforcement",icon:"👁️",desc:"The sanction is misfortune, not a fine. That has proved more durable than statutory protection in many places — and it collapses quickly when belief weakens."},{title:"Deity, not land, ownership",icon:"🛕",desc:"The grove is conceptually owned by the deity. No individual can sell it, which is exactly the property structure that has preserved it."}],SG_THREATS=[{title:"Sanskritisation of the shrine",icon:"🏛️",desc:"When an open-air grove shrine is rebuilt as a formal masonry temple, the surrounding trees are often cleared for the building, parking and processions. The deity survives; the forest does not.",severity:"Critical"},{title:"Urban expansion",icon:"🏘️",desc:"Groves that once sat outside a settlement end up inside it. Manipur's umang lai and many Kerala kavus have shrunk to fragments this way.",severity:"Critical"},{title:"Conversion to plantation",icon:"🌴",desc:"Groves are cleared for coffee, rubber, cashew or eucalyptus, sometimes with the argument that the deity can be relocated to a smaller shrine.",severity:"Critical"},{title:"Roads and infrastructure",icon:"🛣️",desc:"Road widening, transmission lines and quarrying slice groves apart. Small groves rarely survive fragmentation.",severity:"High"},{title:"Loss of oral tradition",icon:"📖",desc:"The rules were never written down. When a generation moves away for work, the specific prohibitions — and the reasons behind them — go with it.",severity:"Critical"},{title:"Invasive species",icon:"🌾",desc:"Lantana, Chromolaena and Prosopis juliflora crowd out grove understorey, and small fragments are the least able to resist them.",severity:"High"},{title:"Grazing pressure",icon:"🐄",desc:"Where common grazing land has shrunk, groves absorb the excess. Trampling and browsing stop regeneration even where no tree is ever cut.",severity:"Moderate"},{title:"Unclear legal status",icon:"📜",desc:"Many groves sit on revenue land, temple land or private holdings with no forest classification, leaving them open to reclassification and sale.",severity:"High"}],SG_CONSERVATION=[{title:"Community Reserves",icon:"🛡️",org:"Wild Life (Protection) Amendment Act, 2002",desc:"Introduced Conservation and Community Reserves, creating for the first time a legal category that can protect community-held land without transferring it to the Forest Department."},{title:"Biodiversity Heritage Sites",icon:"🏅",org:"Biological Diversity Act, 2002",desc:"Allows states to notify areas of high biodiversity value as Biodiversity Heritage Sites, and several notified sites are sacred groves."},{title:"Biodiversity Management Committees",icon:"📋",org:"Biological Diversity Act, 2002",desc:"Local BMCs maintain People's Biodiversity Registers, which have become a practical way of documenting groves that no official survey ever reached."},{title:"Community Forest Resource rights",icon:"🌲",org:"Forest Rights Act, 2006",desc:"Recognises community rights over forest resources and explicitly protects access to customary religious sites, giving grove communities a rights-based footing."},{title:"State documentation drives",icon:"🗺️",org:"State forest departments & ENVIS",desc:"Kerala, Karnataka, Maharashtra, Meghalaya and others have run inventory programmes, though coverage remains uneven and many groves are still unrecorded."},{title:"Litigation over orans",icon:"⚖️",org:"Courts & Rajasthan authorities",desc:"The classification of Rajasthan's orans — whether they count as deemed forest and what that means for their protection — has been the subject of sustained legal contest."}],SG_FACTS=["Estimates of the number of sacred groves in India range from roughly 100,000 to 150,000, with higher figures proposed — but no complete national inventory exists.","A sacred grove has a different name in almost every state: kavu in Kerala, devrai in Maharashtra, sarna in Jharkhand, oran in Rajasthan, law kyntang in Meghalaya.","At Mawphlang in Meghalaya, nothing may be removed from the forest — the prohibition extends to fallen leaves and loose stones.","Kodagu district in Karnataka has more than a thousand sacred groves, one of the densest concentrations recorded anywhere.","Kerala's sarpa kavus were traditionally maintained beside individual houses, making conservation a household rather than village obligation.","Rajasthan's orans permit grazing but forbid cultivation and green felling — which is why they remain open woodland rather than farmland.","Many village springs emerge at the foot of a sacred grove, linking the religious prohibition directly to the drinking water supply.","Sacred groves are conceptually owned by the deity, so no individual has the standing to sell one — a property structure that has protected them for centuries.","The Wild Life (Protection) Amendment Act of 2002 created Community Reserves, the first legal category able to protect community-held groves.","Rebuilding an open-air grove shrine as a masonry temple is now one of the leading causes of grove loss — the deity is preserved while the forest is cleared."],SG_QUIZ=[{q:"What is a sacred grove called in Kerala?",options:["Devrai","Kavu","Oran","Sarna"],answer:1,explain:"Kerala's sacred groves are called kavu; serpent groves specifically are sarpa kavu."},{q:"Mawphlang sacred forest is in which state?",options:["Manipur","Meghalaya","Mizoram","Nagaland"],answer:1,explain:"Mawphlang is in the East Khasi Hills of Meghalaya, managed by the Lyngdoh clan."},{q:'An "oran" is a sacred grove of which state?',options:["Gujarat","Rajasthan","Punjab","Haryana"],answer:1,explain:"Orans are the arid sacred commons of Rajasthan, often centred on khejri trees."},{q:"Which district is known for having over a thousand devarakadus?",options:["Kodagu","Wayanad","Nilgiris","Chikmagalur"],answer:0,explain:"Kodagu (Coorg) in Karnataka has one of the densest concentrations of sacred groves in India."},{q:"Sarna groves are central to the religion of which region?",options:["Konkan coast","Chotanagpur plateau","Rann of Kutch","Brahmaputra valley"],answer:1,explain:"Sarna groves are the ritual centre of Oraon, Munda, Ho and Santal villages across the Chotanagpur plateau."},{q:"Which tree dominates the sarna groves of Jharkhand?",options:["Teak","Sal","Deodar","Banyan"],answer:1,explain:"Sal (Shorea robusta) dominates, and the Sarhul festival marks its flowering."},{q:"Umang Lai groves belong to which community?",options:["Khasi","Meitei","Santal","Kodava"],answer:1,explain:"Umang Lai are the forest-deity groves of the Meitei of Manipur, tied to Lai Haraoba."},{q:"Which 2002 law created Community Reserves as a protection category?",options:["Forest Rights Act","Wild Life (Protection) Amendment Act","Environment Protection Act","Panchayat Extension Act"],answer:1,explain:"The 2002 amendment to the Wild Life (Protection) Act introduced Conservation and Community Reserves."},{q:"Which animal do the Bhimashankar devrais notably shelter?",options:["Snow leopard","Indian giant squirrel","One-horned rhino","Nilgiri tahr"],answer:1,explain:"The shekru, or Indian giant squirrel, needs the tall closed canopy the devrais protect."},{q:"What is now a leading cause of sacred grove loss?",options:["Replacing the open shrine with a masonry temple","Excessive rainfall","Declining tourism","Reforestation programmes"],answer:0,explain:"Rebuilding a grove shrine as a formal temple often means clearing the surrounding trees for the structure and access."}],SG_GALLERY=[{icon:"🌲",title:"Mawphlang",caption:"Moss and epiphyte-laden trees in the Khasi sacred forest, Meghalaya"},{icon:"☕",title:"Kodagu Devarakadu",caption:"An evergreen grove island in the coffee landscape, Karnataka"},{icon:"🐍",title:"Sarpa Kavu",caption:"Serpent stones under old trees, Kerala"},{icon:"🐐",title:"Desert Oran",caption:"Khejri woodland held as sacred grazing commons, Rajasthan"},{icon:"🌳",title:"Sarna Sthal",caption:"Sal grove at the ritual centre of a Chotanagpur village, Jharkhand"},{icon:"🎭",title:"Lai Haraoba",caption:"Ritual performance at an Umang Lai grove, Manipur"},{icon:"💧",title:"Khecheopalri",caption:"The sacred lake and its protected catchment forest, Sikkim"},{icon:"🐿️",title:"Bhimashankar Devrai",caption:"Closed-canopy forest sheltering the shekru, Maharashtra"}];